<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_permission('purchase.view');

$pdo = db();
$id = input_int($_GET, 'id');
$s = $pdo->prepare('SELECT po.*, s.name AS supplier, s.payment_terms_days, w.name AS wh, cu.full_name AS creator, au.full_name AS approver FROM purchase_orders po JOIN suppliers s ON s.id = po.supplier_id JOIN warehouses w ON w.id = po.warehouse_id LEFT JOIN users cu ON cu.id = po.created_by LEFT JOIN users au ON au.id = po.approved_by WHERE po.id = :id');
$s->execute([':id' => $id]); $po = $s->fetch();
if (!$po) { flash('error', 'Purchase order not found.'); redirect('/purchasing/orders.php'); }
if (is_post()) {
    verify_csrf(); $a = input($_POST, 'action');
    try {
        if ($a === 'submit' && can('purchase.create')) { $st = po_submit($id); flash($st === 'approved' ? 'success' : 'info', $st === 'approved' ? 'Purchase order approved.' : 'Sent for approval.'); }
        elseif ($a === 'approve' && can('purchase.approve')) { po_decide($id, true, input($_POST, 'note')); flash('success', 'Purchase order approved.'); }
        elseif ($a === 'reject' && can('purchase.approve')) { po_decide($id, false, input($_POST, 'note')); flash('success', 'Purchase order rejected.'); }
        elseif ($a === 'send' && can('purchase.create')) { po_mark_sent($id); flash('success', 'Marked as sent to the supplier.'); }
        elseif ($a === 'cancel' && can('purchase.create')) { po_cancel($id, input($_POST, 'reason')); flash('success', 'Purchase order cancelled.'); }
        elseif ($a === 'close' && can_any(['purchase.create', 'purchase.receive'])) { po_close($id); flash('success', 'Order closed. The undelivered balance will not be received.'); }
        elseif ($a === 'delete' && can('purchase.create') && in_array($po['status'], ['draft', 'rejected'], true)) { $pdo->prepare('DELETE FROM purchase_orders WHERE id = :id')->execute([':id' => $id]); flash('success', 'Draft deleted.'); redirect('/purchasing/orders.php'); }
    } catch (RuntimeException $e) { flash('error', $e->getMessage()); }
    redirect('/purchasing/order_view.php?id=' . $id);
}
$lines = po_lines_with_balance($id);
$grns = $pdo->query("SELECT g.*, si.bill_no FROM goods_receipts g LEFT JOIN supplier_invoices si ON si.id = g.supplier_invoice_id WHERE g.po_id = $id ORDER BY g.id")->fetchAll();
$bills = $pdo->query("SELECT * FROM supplier_invoices WHERE po_id = $id AND status <> 'void' ORDER BY id")->fetchAll();
$short = array_sum(array_column($lines, 'remaining'));
$billed = $bills || array_filter($grns, fn($g) => $g['supplier_invoice_id']);
$paid = $bills && array_reduce($bills, fn($c, $b) => $c && $b['status'] === 'paid', true);
$cur = match ($po['status']) { 'draft', 'rejected' => 'created', 'pending_approval' => 'created', 'approved' => 'approved', 'sent' => 'sent', 'partially_received' => 'received', 'received', 'closed' => $bills ? ($paid ? 'paid' : 'invoiced') : ($billed ? 'invoiced' : 'received'), default => 'created' };
$pageTitle = $po['po_no'];
require __DIR__ . '/../includes/header.php';
$act = '<a class="btn btn-secondary" target="_blank" href="' . e(app_url('/purchasing/print.php?type=po&id=' . $id)) . '">' . icon('printer', 16) . ' Print / send</a>';
if (in_array($po['status'], ['draft', 'rejected'], true) && can('purchase.create')) $act .= '<a class="btn btn-secondary" href="' . e(app_url('/purchasing/order_form.php?id=' . $id)) . '">' . icon('pencil', 16) . ' Edit</a>';
if (in_array($po['status'], ['approved', 'sent', 'partially_received'], true) && can('purchase.receive')) $act .= '<a class="btn btn-primary" href="' . e(app_url('/purchasing/receive.php?po_id=' . $id)) . '">' . icon('package-plus', 16) . ' Receive goods</a>';
page_header($po['po_no'], '<a class="link" href="' . e(app_url('/purchasing/supplier_view.php?id=' . $po['supplier_id'])) . '">' . e($po['supplier']) . '</a> · ' . e(fmt_date($po['order_date'])) . ' · ' . status_badge($po['status']), $act, [['Purchase orders', '/purchasing/orders.php'], [$po['po_no'], null]]);
if (!in_array($po['status'], ['cancelled', 'rejected'], true)) echo workflow_steps(['created' => 'Created', 'approved' => 'Approved', 'sent' => 'Sent to supplier', 'received' => 'Goods received', 'invoiced' => 'Invoice matched', 'paid' => 'Paid'], $cur);
switch ($po['status']) {
    case 'draft': echo next_step('send', 'Draft purchase order', 'Review the items, then submit. ' . ((float) setting('po_approval_threshold', '0') > 0 && (float) $po['total'] >= (float) setting('po_approval_threshold') ? 'This order is above the approval threshold, so Accounts must approve it.' : 'It will be approved immediately.'), can('purchase.create') ? '<form method="post" class="inline-form">' . csrf_field() . '<input type="hidden" name="action" value="submit"><button class="btn btn-primary" type="submit">' . icon('send', 16) . ' Submit</button></form><form method="post" class="inline-form" data-confirm="Delete this draft?">' . csrf_field() . '<input type="hidden" name="action" value="delete"><button class="btn btn-secondary" type="submit">Delete</button></form>' : '', 'info'); break;
    case 'pending_approval': echo next_step('shield-question', 'Waiting for approval', 'Orders of ' . format_money(setting('po_approval_threshold')) . ' or more need sign-off from Accounts.', can('purchase.approve') ? '<button class="btn btn-primary" type="button" data-modal-open="#decideModal">Review &amp; decide</button>' : '', 'warn'); break;
    case 'rejected': echo next_step('x-circle', 'Rejected', e($po['decision_note'] ?? ''), can('purchase.create') ? '<a class="btn btn-primary" href="' . e(app_url('/purchasing/order_form.php?id=' . $id)) . '">Edit &amp; resubmit</a>' : '', 'bad'); break;
    case 'approved': echo next_step('send', 'Approved — send to the supplier', 'Print or email the purchase order, then mark it as sent. Goods can be received once they arrive.', can('purchase.create') ? '<form method="post" class="inline-form">' . csrf_field() . '<input type="hidden" name="action" value="send"><button class="btn btn-primary" type="submit">Mark as sent</button></form>' : '', 'good'); break;
    case 'sent': echo next_step('truck', 'Waiting for delivery', 'Expected ' . e(fmt_date($po['expected_date'])) . '. When the truck arrives, receive the goods and record what really came.', can('purchase.receive') ? '<a class="btn btn-primary" href="' . e(app_url('/purchasing/receive.php?po_id=' . $id)) . '">Receive goods</a>' : '', 'info'); break;
    case 'partially_received': echo next_step('package-open', 'Short delivery — ' . fmt_qty($short) . ' unit(s) still to come', 'Only part of the order has arrived. Receive the balance when it is delivered, or close the order if it will not come.', (can('purchase.receive') ? '<a class="btn btn-primary" href="' . e(app_url('/purchasing/receive.php?po_id=' . $id)) . '">Receive balance</a>' : '') . '<form method="post" class="inline-form" data-confirm="Close this PO? The undelivered balance will not be received.">' . csrf_field() . '<input type="hidden" name="action" value="close"><button class="btn btn-secondary" type="submit">Close short</button></form>', 'warn'); break;
    case 'received': case 'closed':
        $uninv = array_filter($grns, fn($g) => !$g['supplier_invoice_id']);
        echo $uninv && can('supplier_bills.manage') ? next_step('file-spreadsheet', 'Goods received — record the supplier invoice', 'Match the supplier’s invoice against what was actually received.', '<a class="btn btn-primary" href="' . e(app_url('/purchasing/bill_form.php?supplier_id=' . $po['supplier_id'] . '&grn_id=' . reset($uninv)['id'])) . '">Record invoice</a>', 'good') : next_step('check-circle-2', $po['status'] === 'closed' ? 'Order closed' : 'Fully received', 'All goods have been received.', '', 'good'); break;
    case 'cancelled': echo next_step('x-circle', 'Cancelled', e($po['decision_note'] ?? ''), '', 'bad'); break;
}
?>
<div class="layout-2-1 mb-4">
  <div class="card flush"><div class="card-head"><h3>Items</h3><span class="text-muted text-sm">Deliver to <?= e($po['wh']) ?></span></div>
    <div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th class="num">Ordered</th><th class="num">Received</th><th class="num">Short / remaining</th><th class="num">Unit cost</th><th class="num">Line total</th></tr></thead><tbody>
    <?php foreach ($lines as $l): $rem = (int) $l['remaining']; ?>
      <tr><td><span class="strong"><?= e($l['name']) ?></span> <?= $l['tracking'] !== 'none' ? '<span class="tag ' . $l['tracking'] . '">' . e($l['tracking']) . '</span>' : '' ?><div class="cell-sub mono"><?= e($l['code']) ?></div></td><td class="num"><?= fmt_pack_qty((int) $l['qty'], (int) $l['pack_factor'], $l['pack_name'], $l['base_unit']) ?></td><td class="num <?= (int) $l['received_qty'] ? 'strong text-success' : 'text-muted' ?>"><?= (int) $l['received_qty'] ? fmt_qty($l['received_qty']) : '—' ?></td><td class="num <?= $rem > 0 && in_array($po['status'], ['partially_received', 'closed', 'received'], true) ? 'text-error strong' : 'text-secondary' ?>"><?= $rem > 0 ? fmt_qty($rem) : '—' ?></td><td class="num"><?= format_money($l['unit_cost'] * $l['pack_factor']) ?><div class="cell-sub">per <?= e($l['pack_factor'] > 1 ? $l['pack_name'] : $l['base_unit']) ?></div></td><td class="num strong"><?= format_money($l['line_total']) ?></td></tr>
    <?php endforeach; ?></tbody>
    <tfoot><tr><td colspan="5" class="text-right">Subtotal</td><td class="num"><?= format_money($po['subtotal']) ?></td></tr><tr><td colspan="5" class="text-right"><?= e(setting('tax_name', 'VAT')) ?></td><td class="num"><?= format_money($po['tax_total']) ?></td></tr><tr><td colspan="5" class="text-right">Order total</td><td class="num"><?= format_money($po['total']) ?></td></tr></tfoot></table></div></div>
  <div class="grid">
    <div class="card"><h3 class="mb-3">Details</h3><dl class="desc-list"><dt>Supplier</dt><dd><?= e($po['supplier']) ?></dd><dt>Terms</dt><dd><?= (int) $po['payment_terms_days'] ?> days</dd><dt>Expected</dt><dd><?= e(fmt_date($po['expected_date'])) ?></dd><dt>Created by</dt><dd><?= e($po['creator'] ?? '—') ?></dd><?php if ($po['approved_by']): ?><dt>Approved by</dt><dd><?= e($po['approver']) ?><div class="cell-sub"><?= e(fmt_datetime($po['approved_at'])) ?></div></dd><?php endif; ?></dl><?php if ($po['notes']): ?><div class="callout mt-3"><?= e($po['notes']) ?></div><?php endif; ?></div>
    <?php if (in_array($po['status'], ['draft', 'pending_approval', 'approved', 'sent'], true) && can('purchase.create')): ?><button class="btn btn-danger-outline" type="button" data-modal-open="#cancelModal">Cancel order</button><?php endif; ?>
    <a class="link text-sm" href="<?= e(app_url('/audit.php?entity=purchase_order&entity_id=' . $id)) ?>">Audit trail →</a>
  </div>
</div>
<div class="grid grid-2">
  <div class="card flush"><div class="card-head"><h3>Goods received</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Receipt</th><th>Date</th><th class="num">Value</th><th>Invoice</th></tr></thead><tbody><?php foreach ($grns as $g): ?><tr><td class="strong"><a href="<?= e(app_url('/purchasing/grn_view.php?id=' . $g['id'])) ?>"><?= e($g['grn_no']) ?></a><div class="cell-sub"><?= e($g['supplier_ref'] ?? '') ?></div></td><td class="text-secondary nowrap"><?= e(fmt_date($g['received_date'])) ?></td><td class="num"><?= format_money($g['total_value']) ?></td><td><?= $g['bill_no'] ? '<a class="link" href="' . e(app_url('/purchasing/bill_view.php?id=' . $g['supplier_invoice_id'])) . '">' . e($g['bill_no']) . '</a>' : '<span class="badge badge-neutral">Not invoiced</span>' ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$grns) echo empty_state('package', 'Nothing received yet'); ?></div></div>
  <div class="card flush"><div class="card-head"><h3>Supplier invoices</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th class="num">Total</th><th>Match</th><th>Status</th></tr></thead><tbody><?php foreach ($bills as $b): ?><tr><td class="strong"><a href="<?= e(app_url('/purchasing/bill_view.php?id=' . $b['id'])) ?>"><?= e($b['bill_no']) ?></a><div class="cell-sub"><?= e($b['supplier_ref']) ?></div></td><td class="num"><?= format_money($b['total']) ?></td><td><?= status_badge($b['match_status']) ?></td><td><?= status_badge($b['status']) ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$bills) echo empty_state('file-spreadsheet', 'No invoice recorded'); ?></div></div>
</div>
<?php if (can('purchase.approve') && $po['status'] === 'pending_approval'): ?><div class="modal-overlay" id="decideModal" hidden><div class="modal sm"><div class="modal-header"><h3>Decide on <?= e($po['po_no']) ?></h3><button class="modal-close" type="button" data-modal-close>&times;</button></div><div class="callout info mb-3">Total <strong><?= format_money($po['total']) ?></strong> to <?= e($po['supplier']) ?>.</div><form method="post"><?= csrf_field() ?><div class="form-group"><label>Note <span class="label-opt">(required when rejecting)</span></label><input class="form-control" type="text" name="note" maxlength="255"></div><div class="modal-footer"><button class="btn btn-secondary" type="button" data-modal-close>Cancel</button><button class="btn btn-danger-outline" type="submit" name="action" value="reject" data-no-busy>Reject</button><button class="btn btn-primary" type="submit" name="action" value="approve" data-no-busy>Approve</button></div></form></div></div><?php endif; ?>
<?php if (can('purchase.create')): ?><div class="modal-overlay" id="cancelModal" hidden><div class="modal sm"><div class="modal-header"><h3>Cancel purchase order</h3><button class="modal-close" type="button" data-modal-close>&times;</button></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><div class="form-group"><label>Reason</label><input class="form-control" type="text" name="reason" maxlength="255"></div><div class="modal-footer"><button class="btn btn-secondary" type="button" data-modal-close>Keep</button><button class="btn btn-danger" type="submit">Cancel order</button></div></form></div></div><?php endif; ?>
<?php require __DIR__ . '/../includes/footer.php'; ?>
